import subprocess

def run_bytes(b, args=[]):
    r=subprocess.run(["./executable"]+args, input=b, capture_output=True)
    return r.stdout.decode().rstrip("\n")

def pixel_count_and_width(s):
    out=run_bytes((s+"\n").encode())
    # count dots in top row only? Simpler: total braille chars and filled dots count for single line input (row0)
    # For single line, dots are dot1 (col even) and dot4 (col odd)
    counts=[]
    for ch in out:
        v=ord(ch)-0x2800
        counts.append(bin(v).count("1"))
    return out, len(out), sum(counts)

tests=[
 ("a"*i) for i in range(1,11)
]+[
 ("é"*i) for i in range(1,11)
]+[
 ("中"*i) for i in range(1,11)
]+[
 ("α"*i) for i in range(1,11)
]+[
 ("😀"*i) for i in range(1,7)
]+[
 (" "*i) for i in range(1,11)
]+[
 ("aé"*i) for i in range(1,5)
]+[
 ("éa"*i) for i in range(1,5)
]

for t in tests:
    out,l,c=pixel_count_and_width(t)
    print(f"{t!r:30} -> out={out!r} braille_len={l} filled_top={c}")

