{"command":"python3 << 'PY'
import subprocess
def run(inp, args=[]):
    r=subprocess.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return r.stdout.decode(), r.stderr.decode(), r.returncode
def grid(inp, args=[]):
    out,err,rc=run(inp,args)
    lines=out.rstrip("\n").split("\n") if out.strip("\n")!="" or out else []
    # Actually handle empty braille lines: out may be "⠀\n"
    if out:
        blines=out.rstrip("\n").split("\n")
    else:
        blines=[]
    pix=[]
    for bl in blines:
        rows=[[] for _ in range(4)]
        mapping=[[0x01,0x08],[0x02,0x10],[0x04,0x20],[0x40,0x80]]
        for ch in bl:
            v=ord(ch)-0x2800 if 0x2800<=ord(ch)<=0x28ff else 0
            for r in range(4):
                for c in range(2):
                    rows[r].append('#' if v&mapping[r][c] else '.')
        pix.extend(''.join(r) for r in rows)
    return out,pix

def show(inp, args=[]):
    out,pix=grid(inp,args)
    print(f"inp={inp!r} args={args} out={out!r}")
    for r in pix: print("  "+r)
    print()

# vertical scaling
for v in ["0.5","1","2","1.5","0.25","3","0"]:
    show("a\nb\nc\nd\n", ["-V",v])
for h in ["0.5","2","1.5","0.25","3"]:
    show("aaa\naaaaaa\n  aa\n", ["-H",h])

# indentation scaling
for h in ["0.5","2","0.3","1.7"]:
    show("  a\n    b\n      c\n", ["-H",h])

PY
"}

