def run(inp, args=[]):
    r=subprocess.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return r.stdout.decode()
def pix_top(s, args=[]):
    out=run(s+"\n",args).rstrip("\n")
    arr=[]
    for ch in out:
