    ("SPACE", "\u0020"),("TAB","\t"),("VT","\x0b"),("FF","\x0c"),("CR","\r"),
    ("NEL","\u0085"),("NBSP","\u00a0"),("OGHAM","\u1680"),("ENQ","\u2000"),("EMSP","\u2003"),("THIN","\u2009"),("HAIR","\u200a"),
    ("ZWSP","\u200b"),("LS","\u2028"),("PS","\u2029"),("NNBSP","\u202f"),("MMSP","\u205f"),("IDEO","\u3000"),("FEFF","\ufeff"),
    ("NUL","\x00"),("BEL","\x07"),("BS","\x08"),("FS","\x1c"),("GS","\x1d"),("RS","\x1e"),("US","\x1f"),
    ("DEL","\x7f"),("ZWJ","\u200d"),("ZWNJ","\u200c"),("SOFT_HYPHEN","\u00ad"),
