import subprocess
def run(args, inp):
    r=subprocess.run(["./executable"]+args, input=inp.encode(), capture_output=True)
    return r.stdout.decode(), r.stderr.decode(), r.returncode

def scaled_rows(v, n=16):
    inp="".join(" "*i+"a\n" for i in range(n))
    out,err,rc=run(["--vertical-scale",str(v)], inp)
    rows=[]
    if out:
        for bl in out.rstrip("\n").split("\n"):
            # decode rows
            tmp=[[] for _ in range(4)]
            mp=[[0x01,0x08],[0x02,0x10],[0x04,0x20],[0x40,0x80]]
            for ch in bl:
                vv=ord(ch)-0x2800 if 0x2800<=ord(ch)<=0x28ff else -1
                for rr in range(4):
                    for cc in range(2):
                        tmp[rr].append('#' if vv>=0 and vv&mp[rr][cc] else '.')
            rows.extend(''.join(r) for r in tmp)
    # for each pixel row, find x position of #
    pos=[]
    for r in rows:
        idx=[i for i,c in enumerate(r) if c=='#']
        pos.append(idx)
    return pos, out

for v in ["0.9","1","1.1","1.5","2","3","10","100","1000","1e10","1e100","inf"]:
    pos,out=scaled_rows(v)
    print(v, pos)
