use clap::builder::styling::{AnsiColor, Effects};
use clap::builder::Styles;
use clap::{Arg, ArgAction, ArgGroup, Command};
use std::io::IsTerminal;

fn styles() -> Styles {
    Styles::styled()
        .header(AnsiColor::Yellow.on_default().effects(Effects::BOLD))
        .usage(AnsiColor::Yellow.on_default().effects(Effects::BOLD))
        .literal(AnsiColor::Green.on_default().effects(Effects::BOLD))
        .placeholder(AnsiColor::Cyan.on_default())
}

fn tty_width() -> Option<usize> {
    // Best-effort mirror of the width lookup used for help wrapping: a size
    // reported by the terminal itself wins, with a zero column count treated
    // as "no usable size".
    unsafe {
        let mut size: libc::winsize = std::mem::zeroed();
        let result = libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut size);
        if result == 0 && size.ws_col > 0 {
            Some(size.ws_col as usize)
        } else {
            None
        }
    }
}

fn detected_term_width() -> Option<usize> {
    if std::io::stdout().is_terminal() {
        if let Some(width) = tty_width() {
            return Some(width);
        }
    }
    std::env::var_os("COLUMNS")?
        .to_str()?
        .parse::<usize>()
        .ok()
}

fn build(grouped: bool) -> Command {
    let mut cmd = Command::new("code-minimap")
        .version("0.6.8")
        .disable_version_flag(true)
        .about("A high performance code minimap generator")
        .next_line_help(true)
        .styles(styles());

    if let Some(width) = detected_term_width() {
        cmd = cmd.term_width(width);
    }

    if grouped {
        cmd = cmd.group(
            ArgGroup::new("code-minimap")
                .args([
                    "file",
                    "hscale",
                    "vscale",
                    "padding",
                    "encoding",
                    "version",
                ])
                .multiple(true)
                .required(true),
        );
    }

    cmd.arg(
        Arg::new("file")
            .value_name("FILE")
            .help("File to read")
            .value_parser(clap::value_parser!(std::path::PathBuf)),
    )
    .arg(
        Arg::new("hscale")
            .value_name("HSCALE")
            .short('H')
            .long("horizontal-scale")
            .help("Specify horizontal scale factor")
            .default_value("1.0")
            .value_parser(clap::value_parser!(f64)),
    )
    .arg(
        Arg::new("vscale")
            .value_name("VSCALE")
            .short('V')
            .long("vertical-scale")
            .help("Specify vertical scale factor")
            .default_value("1.0")
            .value_parser(clap::value_parser!(f64)),
    )
    .arg(
        Arg::new("padding")
            .value_name("PADDING")
            .long("padding")
            .help("Specify padding width")
            .value_parser(clap::value_parser!(usize)),
    )
    .arg(
        Arg::new("encoding")
            .value_name("ENCODING")
            .long("encoding")
            .help("Specify input encoding")
            .default_value("utf8-lossy")
            .ignore_case(true)
            .value_parser(["utf8-lossy", "utf8"]),
    )
    .arg(
        Arg::new("version")
            .long("version")
            .help("Print version")
            .action(ArgAction::Version),
    )
    .subcommand(
        Command::new("completion")
            .about("Generate shell completion file")
            .arg(
                Arg::new("shell")
                    .value_name("SHELL")
                    .required(true)
                    .help("Target shell name")
                    .value_parser(clap::value_parser!(clap_complete::Shell)),
            ),
    )
}

pub fn build_cli() -> Command {
    build(false)
}

pub fn build_grouped_cli() -> Command {
    build(true)
}
