use std::io::Write;

/// A horizontal span of a source line, in byte offsets.
///
/// `start` is the offset of the first non-whitespace character and `end` is
/// one past the offset of the last non-whitespace character.  Keeping the
/// offsets (rather than a trimmed length) is deliberate: it is what makes a
/// multi-byte character followed by other text widen the span by its byte
/// position, while a trailing multi-byte character contributes only its
/// starting position.
type Span = (usize, usize);

fn line_span(line: &str) -> Option<Span> {
    let first = line.find(|c: char| !c.is_whitespace());
    let last = line.rfind(|c: char| !c.is_whitespace());
    match (first, last) {
        (Some(start), Some(last)) => Some((start, last + 1)),
        _ => None,
    }
}

fn merge_span(target: &mut Option<Span>, span: Option<Span>) {
    if let Some((start, end)) = span {
        *target = Some(match *target {
            None => (start, end),
            Some((old_start, old_end)) => (old_start.min(start), old_end.max(end)),
        });
    }
}

fn braille_bit(column: usize, row: usize) -> u8 {
    match (column, row) {
        (0, 0) => 0x01,
        (0, 1) => 0x02,
        (0, 2) => 0x04,
        (0, 3) => 0x40,
        (1, 0) => 0x08,
        (1, 1) => 0x10,
        (1, 2) => 0x20,
        (1, 3) => 0x80,
        _ => 0,
    }
}

fn scaled(value: usize, scale: f64) -> usize {
    (value as f64 * scale) as usize
}

pub fn render(
    input: &str,
    hscale: f64,
    vscale: f64,
    padding: Option<usize>,
    writer: &mut dyn Write,
) {
    let lines: Vec<&str> = input.lines().collect();
    if lines.is_empty() {
        return;
    }

    let spans: Vec<Option<Span>> = lines.iter().map(|line| line_span(line)).collect();
    let source_width = spans
        .iter()
        .filter_map(|span| span.map(|(_, end)| end))
        .max()
        .unwrap_or(1);

    // Collapse source lines into output pixel rows.  A new row begins when
    // the scaled line index changes; lines landing on the same index are
    // merged by taking the union of their horizontal spans.
    let mut rows: Vec<Option<Span>> = Vec::new();
    let mut previous_scaled_y: Option<usize> = None;
    for (index, span) in spans.iter().enumerate() {
        let scaled_y = scaled(index, vscale);
        if previous_scaled_y != Some(scaled_y) {
            rows.push(None);
            previous_scaled_y = Some(scaled_y);
