mod cli;
mod core;

use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap_complete::Shell;
use std::io::{self, BufRead, BufReader, BufWriter, Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

#[derive(Clone, Copy, PartialEq, Eq)]
enum InputEncoding {
    Utf8Lossy,
    Utf8,
}

fn completion_text(shell: Shell) -> &'static str {
    match shell {
        Shell::Bash => include_str!("completions/bash.txt"),
        Shell::Elvish => include_str!("completions/elvish.txt"),
        Shell::Fish => include_str!("completions/fish.txt"),
        Shell::PowerShell => include_str!("completions/powershell.txt"),
        Shell::Zsh => include_str!("completions/zsh.txt"),
        _ => "",
    }
}

fn suggested_user_argument(err: &clap::Error) -> bool {
    if err.kind() != ErrorKind::UnknownArgument {
        return false;
    }
    match err.get(ContextKind::SuggestedArg) {
        Some(ContextValue::String(value)) => matches!(
            value.as_str(),
            "--horizontal-scale"
                | "--vertical-scale"
                | "--padding"
                | "--encoding"
                | "--version"
        ),
        _ => false,
    }
}

/// Line iterator for the lossy encoding: raw lines are split on `\n` (with a
/// preceding `\r` removed, matching the usual line handling) and each line
/// is decoded with replacement characters for invalid sequences.
struct LossyLines {
    reader: BufReader<Box<dyn Read>>,
}

impl Iterator for LossyLines {
    type Item = io::Result<String>;

    fn next(&mut self) -> Option<Self::Item> {
        let mut bytes = Vec::new();
        match self.reader.read_until(b'\n', &mut bytes) {
            Ok(0) => None,
            Ok(_) => {
                if bytes.last() == Some(&b'\n') {
                    bytes.pop();
                    if bytes.last() == Some(&b'\r') {
                        bytes.pop();
                    }
                }
                Some(Ok(String::from_utf8_lossy(&bytes).into_owned()))
            }
            Err(err) => Some(Err(err)),
        }
    }
}

fn open_reader(file: Option<&PathBuf>) -> io::Result<BufReader<Box<dyn Read>>> {
    let reader: Box<dyn Read> = match file {
        Some(path) => Box::new(std::fs::File::open(path)?),
        None => Box::new(io::stdin()),
    };
    Ok(BufReader::new(reader))
}

fn run() -> Result<(), io::Error> {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let command = cli::build_cli();
    let matches = match command.clone().try_get_matches_from(&args) {
        Ok(matches) => matches,
        Err(err) => {
            if suggested_user_argument(&err) {
                let grouped = cli::build_grouped_cli();
                if let Err(grouped_err) = grouped.try_get_matches_from(&args) {
                    grouped_err.exit();
                }
            }
            err.exit();
        }
    };

    if let Some(sub_matches) = matches.subcommand_matches("completion") {
        let shell = sub_matches
            .get_one::<Shell>("shell")
            .copied()
            .unwrap_or(Shell::Bash);
        let stdout = io::stdout();
        let mut writer = BufWriter::new(stdout.lock());
        let _ = writer.write_all(completion_text(shell).as_bytes());
        let _ = writer.flush();
        return Ok(());
    }

    let file = matches.get_one::<PathBuf>("file");
    let hscale = matches.get_one::<f64>("hscale").copied().unwrap_or(1.0);
