//! Minimal terminal-size lookup used as a local dependency.
//!
//! The size is obtained from the terminal attached to standard output via
//! the `TIOCGWINSZ` ioctl.  When standard output is not a terminal, or the
//! terminal reports a zero dimension, `None` is returned so callers can
//! apply their own fallbacks.

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Returns the size of the terminal attached to standard output, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(libc::STDOUT_FILENO)
}

/// Returns the size of the terminal attached to the given file descriptor.
pub fn terminal_size_of(fd: std::os::unix::io::RawFd) -> Option<(Width, Height)> {
    unsafe {
        let mut size: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut size) == 0 && size.ws_col > 0 && size.ws_row > 0 {
            Some((Width(size.ws_col), Height(size.ws_row)))
        } else {
            None
        }
    }
}
