import os, pty, struct, fcntl, termios, subprocess, sys

def run_pty(path, args, cols, env_extra=None):
    pid, fd = pty.fork()
    if pid==0:
        env=os.environ.copy()
        if env_extra: env.update(env_extra)
        os.execve(path, [path]+args, env)
