            match name {
                "horizontal-scale" | "vertical-scale" | "padding" | "encoding" => {
                    if long.contains('=') {
                        has_user_argument = true;
                    } else {
                        expecting_value = true;
                    }
                }
                "version" => has_user_argument = true,
                "help" => {}
                _ => return has_user_argument,
            }
            continue;
