use std::io::Write;

/// A horizontal span of a source line, in byte offsets.
///
/// `start` is the offset of the first non-whitespace character and `end`
/// is one past the offset of the last non-whitespace character.  Keeping
/// offsets rather than a trimmed length is deliberate: it is what makes a
/// multi-byte character followed by other text widen the span by its byte
/// position, while a trailing multi-byte character contributes only its
/// starting position.
type Span = (usize, usize);

fn line_span(line: &str) -> Option<Span> {
    match (
        line.find(|c: char| !c.is_whitespace()),
        line.rfind(|c: char| !c.is_whitespace()),
    ) {
        (Some(start), Some(last)) => Some((start, last + 1)),
        _ => None,
    }
}

fn merge_span(target: &mut Option<Span>, span: Option<Span>) {
    if let Some((start, end)) = span {
        *target = Some(match *target {
            None => (start, end),
            Some((old_start, old_end)) => (old_start.min(start), old_end.max(end)),
        });
    }
}

fn braille_bit(column: usize, row: usize) -> u8 {
    [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]][row][column]
}

fn scaled(value: usize, scale: f64) -> usize {
    (value as f64 * scale) as usize
}

/// Incremental minimap renderer.
///
/// Source lines are collapsed into pixel rows (lines whose scaled
/// vertical position coincides share a row, merged as the union of their
/// spans).  Groups of four pixel rows are emitted as one line of braille
/// cells as soon as the group is known to be complete, so a read error
/// part-way through the input leaves earlier groups already written.
pub struct Renderer<W: Write> {
    hscale: f64,
    vscale: f64,
    padding: Option<usize>,
    writer: W,
    rows: Vec<Option<Span>>,
    previous_scaled_y: Option<usize>,
    line_index: usize,
}

impl<W: Write> Renderer<W> {
    pub fn new(hscale: f64, vscale: f64, padding: Option<usize>, writer: W) -> Self {
        Self {
            hscale,
            vscale,
            padding,
            writer,
            rows: Vec::new(),
            previous_scaled_y: None,
            line_index: 0,
        }
    }

    pub fn push_line(&mut self, line: &str) {
        let index = self.line_index;
        self.line_index += 1;
        let scaled_y = scaled(index, self.vscale);
        if self.previous_scaled_y != Some(scaled_y) {
            self.rows.push(None);
            self.previous_scaled_y = Some(scaled_y);
        }
        if let Some(current) = self.rows.last_mut() {
            merge_span(current, line_span(line));
        }
        // A group of four pixel rows is complete once it is full and the
        // next source line would start a different pixel row; whether
        // that happens follows from the scale alone, without reading it.
        if self.rows.len() == 4 && scaled(index + 1, self.vscale) != scaled_y {
            self.write_rows();
        }
    }

    pub fn finish(&mut self) {
        if !self.rows.is_empty() {
            self.write_rows();
        }
        let _ = self.writer.flush();
    }

    fn write_rows(&mut self) {
        let rows = std::mem::take(&mut self.rows);
        // A group of four pixel rows is rendered independently, including
        // its width: it only spans the widest line inside its own group,
        // not the widest line of the whole input.
        let source_width = rows
            .iter()
            .filter_map(|span| span.map(|(_, end)| end))
            .max()
            .unwrap_or(1);
        let pixel_width = scaled(source_width, self.hscale);
        let cell_width = pixel_width.div_ceil(2);
        let mut cells = vec![0u8; cell_width];
        for (sub_row, span) in rows.iter().enumerate() {
            if let Some((start, end)) = span {
                let from = scaled(*start, self.hscale);
                let until = scaled(*end, self.hscale);
                for x in from..until {
                    cells[x / 2] |= braille_bit(x % 2, sub_row);
                }
            }
        }
        let mut line = String::new();
        for cell in cells {
            line.push(char::from_u32(0x2800 + cell as u32).unwrap_or('\u{2800}'));
        }
        if let Some(padding) = self.padding {
            let padded = format!("{:width$}", line, width = padding);
            let _ = writeln!(self.writer, "{}", padded);
        } else {
            let _ = writeln!(self.writer, "{}", line);
        }
        let _ = self.writer.flush();
    }
}
