                    expecting_value = false;
                }
                _ => {
                    expecting_value = false;
                    unresolved_option = true;
                    continue;
                }
            }
        }

        let Some(text) = token else {
            resolved_option |= unresolved_option;
            unresolved_option = false;
            continue;
