            continue;
        }
        for (index, ch) in text[1..].char_indices() {
            match ch {
                'H' | 'V' => {
                    if index + ch.len_utf8() < text[1..].len() {
                        resolved_option = true;
                    } else {
                        expecting_value = true;
                    }
                    break;
                }
                'h' => break,
                _ => return false,
            }
        }
    }
    resolved_option
}

